      if (poziciya.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "add", poziciya, fl_number(1.0), error));
      fl_value fl_t793 = fl_nothing();
      FL_TRY(fl_field_get(ctx, chtenie, "съедено", &fl_t793, error));
      if (fl_t793.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", fl_t793, fl_number(1.0), error));
      /* хвостовой вызов «Сканировать» — отскок, а не кадр стека */
      bounce->args[0] = fl_t791;
      bounce->args[1] = fl_t792;
      bounce->args[2] = fl_number(poziciya.as.number + 1.0);
      bounce->args[3] = fl_number(fl_t793.as.number - 1.0);
      bounce->next = kompilyator_flang_skanirovat_step;
