/*
 * Функция flang «Строка продолжается».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param rezhim — «режим»: «Режим»
 * @return значение
 */
fl_status kompilyator_flang_stroka_prodolzhaetsya(fl_ctx *ctx, fl_value rezhim, fl_value *result, fl_error *error) {
  if (fl_variant_is(rezhim, "Начало")) {
    *result = fl_flag(false);
    return FL_OK;
  } else if (fl_variant_is(rezhim, "Тело")) {
    *result = fl_flag(false);
    return FL_OK;
  } else if (fl_variant_is(rezhim, "Блок в начале")) {
    *result = fl_flag(true);
    return FL_OK;
  } else if (fl_variant_is(rezhim, "Блок в теле")) {
    *result = fl_flag(true);
    return FL_OK;
  } else if (fl_variant_is(rezhim, "В кавычках")) {
    *result = fl_flag(true);
    return FL_OK;
  } else {
    return fl_match_fail(ctx, rezhim, error);
  }
}

