/* Тело «Куски на поверхности»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_kuski_na_poverhnosti_body(fl_ctx *ctx, fl_value chasti, fl_value poverhnost, fl_value citata, fl_value gotovo, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(chasti)) {
      *result = gotovo;
      return FL_OK;
    } else if (fl_chain_cons(chasti)) {
      const fl_value golova = fl_chain_head(chasti); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(chasti); /* хвост «хвост» */
      bool fl_t1942 = false;
      FL_TRY(fl_cond(ctx, citata, &fl_t1942, error));
      fl_value fl_t1943 = fl_nothing();
      if (fl_t1942) {
        fl_t1943 = fl_flag(false);
      } else {
        fl_t1943 = fl_flag(true);
      }
      bool fl_t1944 = false;
      FL_TRY(fl_cond(ctx, citata, &fl_t1944, error));
      fl_value fl_t1945 = fl_nothing();
      if (fl_t1944) {
        fl_value fl_t1946 = fl_nothing(); /* «пусто» */
        FL_TRY(fl_b_pusto(ctx, hvost, &fl_t1946, error));
        bool fl_t1947 = false;
        FL_TRY(fl_cond(ctx, fl_t1946, &fl_t1947, error));
        fl_value fl_t1948 = fl_nothing();
        if (fl_t1947) {
          fl_t1948 = fl_flag(false);
        } else {
          fl_t1948 = fl_flag(true);
        }
        fl_t1945 = fl_t1948;
      } else {
        fl_t1945 = fl_flag(false);
      }
      bool fl_t1949 = false;
      FL_TRY(fl_cond(ctx, fl_t1945, &fl_t1949, error));
      fl_value fl_t1950 = fl_nothing();
      if (fl_t1949) {
        fl_value fl_t1951 = fl_nothing();
        FL_TRY(kompilyator_flang_citata_na_poverhnosti(ctx, golova, poverhnost, &fl_t1951, error));
        fl_t1950 = fl_t1951;
      } else {
        fl_t1950 = golova;
      }
      fl_value fl_t1952 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t1950, gotovo, &fl_t1952, error));
      const fl_value fl_t1953 = poverhnost;
      chasti = hvost;
      poverhnost = fl_t1953;
      citata = fl_t1943;
      gotovo = fl_t1952;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Куски на поверхности", error));
      continue;
    } else {
      return fl_match_fail(ctx, chasti, error);
    }
  }
}

/*
 * Функция flang «Куски на поверхности».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param chasti — «части»: список: строка
 * @param poverhnost — «поверхность»: строка
 * @param citata — «цитата»
 * @param gotovo — «готово»: список: строка
 * @return значение: список: строка
 */
fl_status kompilyator_flang_kuski_na_poverhnosti(fl_ctx *ctx, fl_value chasti, fl_value poverhnost, fl_value citata, fl_value gotovo, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Куски на поверхности", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_kuski_na_poverhnosti_body(ctx, chasti, poverhnost, citata, gotovo, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

