/* Тело «Снять окончание»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_snyat_okonchanie_body(fl_ctx *ctx, fl_value nizhnee, fl_value okonchaniya, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(okonchaniya)) {
      *result = nizhnee;
      return FL_OK;
    } else if (fl_chain_cons(okonchaniya)) {
      const fl_value okonchanie = fl_chain_head(okonchaniya); /* голова «окончание» */
      const fl_value prochie = fl_chain_tail(okonchaniya); /* хвост «прочие» */
      fl_value fl_t2131 = fl_nothing(); /* «длина» */
      FL_TRY(fl_b_dlina(ctx, nizhnee, &fl_t2131, error));
      fl_value fl_t2132 = fl_nothing(); /* «длина» */
      FL_TRY(fl_b_dlina(ctx, okonchanie, &fl_t2132, error));
      if (fl_t2131.tag != FL_NUMBER || fl_t2132.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", fl_t2131, fl_t2132, error));
      const fl_value ostatok = fl_number(fl_t2131.as.number - fl_t2132.as.number); /* пусть «остаток» */
      fl_value fl_t2133 = fl_nothing();
      FL_TRY(kompilyator_flang_konchaetsya_na(ctx, nizhnee, okonchanie, &fl_t2133, error));
      bool fl_t2134 = false;
      FL_TRY(fl_cond(ctx, fl_t2133, &fl_t2134, error));
      fl_value fl_t2135 = fl_nothing();
      if (fl_t2134) {
        fl_value fl_t2136 = fl_nothing();
        FL_TRY(kompilyator_flang_naimenshaya_osnova(ctx, &fl_t2136, error));
        if (ostatok.tag != FL_NUMBER || fl_t2136.tag != FL_NUMBER) FL_TRY(fl_not_order(ctx, ostatok, fl_t2136, error));
        fl_t2135 = fl_flag(ostatok.as.number >= fl_t2136.as.number);
      } else {
        fl_t2135 = fl_flag(false);
      }
      bool fl_t2137 = false;
      FL_TRY(fl_cond(ctx, fl_t2135, &fl_t2137, error));
      if (fl_t2137) {
        fl_value fl_t2138 = fl_nothing(); /* «подстрока» */
        FL_TRY(fl_b_podstroka(ctx, nizhnee, fl_number(1.0), ostatok, &fl_t2138, error));
        *result = fl_t2138;
        return FL_OK;
      } else {
        const fl_value fl_t2139 = nizhnee;
        nizhnee = fl_t2139;
        okonchaniya = prochie;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Снять окончание", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, okonchaniya, error);
    }
  }
}

/*
 * Функция flang «Снять окончание».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param nizhnee — «нижнее»: строка
 * @param okonchaniya — «окончания»: список: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_snyat_okonchanie(fl_ctx *ctx, fl_value nizhnee, fl_value okonchaniya, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Снять окончание", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_snyat_okonchanie_body(ctx, nizhnee, okonchaniya, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

