/* Шаг батута для «Собрать поля»: значение либо отскок к соседу по рекурсии. */
static fl_status kompilyator_flang_sobrat_polya_step(fl_ctx *ctx, const fl_value *args, fl_bounce *bounce, fl_value *result,
                                                     fl_error *error) {
  fl_value polya = args[0]; /* «поля» */
  fl_value gotovye = args[1]; /* «готовые» */
  fl_value sbor = args[2]; /* «сбор» */
  fl_value mesto = args[3]; /* «место» */
  if (fl_chain_empty(polya)) {
    fl_value fl_t16063[2];
    fl_t16063[0] = gotovye; /* «поля» */
    fl_t16063[1] = sbor; /* «сбор» */
    fl_value fl_t16062 = fl_nothing();
    FL_TRY(fl_record_new(ctx, kompilyator_flang_names_113, fl_t16063, 2, &fl_t16062, error));
    *result = fl_t16062;
    return FL_OK;
  } else if (fl_chain_cons(polya)) {
    const fl_value golova = fl_chain_head(polya); /* голова «голова» */
    const fl_value hvost = fl_chain_tail(polya); /* хвост «хвост» */
    /* хвостовой вызов «Собрать поле» — отскок, а не кадр стека */
    bounce->args[0] = golova;
    bounce->args[1] = hvost;
    bounce->args[2] = gotovye;
    bounce->args[3] = sbor;
    bounce->args[4] = mesto;
    bounce->next = kompilyator_flang_sobrat_pole_step;
    return FL_OK;
  } else {
    return fl_match_fail(ctx, polya, error);
  }
}

