/* Тело «Место в именах»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_mesto_v_imenah_body(fl_ctx *ctx, fl_value imena, fl_value imya, fl_value nomer, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(imena)) {
      *result = fl_number(0.0);
      return FL_OK;
    } else if (fl_chain_cons(imena)) {
      const fl_value g = fl_chain_head(imena); /* голова «г» */
      const fl_value h = fl_chain_tail(imena); /* хвост «х» */
      bool fl_t24913 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(g, imya)), &fl_t24913, error));
      if (fl_t24913) {
        *result = nomer;
        return FL_OK;
      } else {
        if (nomer.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "add", nomer, fl_number(1.0), error));
        const fl_value fl_t24914 = imya;
        const fl_value fl_t24915 = fl_number(nomer.as.number + 1.0);
        imena = h;
        imya = fl_t24914;
        nomer = fl_t24915;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Место в именах", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, imena, error);
    }
  }
}

