/* Тело «Пройти цепочку»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_proyti_cepochku_body(fl_ctx *ctx, fl_value shagi, fl_value hod, fl_value obstanovka, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(shagi)) {
      *result = hod;
      return FL_OK;
    } else if (fl_chain_cons(shagi)) {
      const fl_value g = fl_chain_head(shagi); /* голова «г» */
      const fl_value h = fl_chain_tail(shagi); /* хвост «х» */
      fl_value fl_t26552 = fl_nothing();
      FL_TRY(kompilyator_flang_shagnut_po_cepochke(ctx, g, hod, obstanovka, &fl_t26552, error));
      const fl_value fl_t26553 = obstanovka;
      shagi = h;
      hod = fl_t26552;
      obstanovka = fl_t26553;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пройти цепочку", error));
      continue;
    } else {
      return fl_match_fail(ctx, shagi, error);
    }
  }
}

