fl_status kompilyator_flang_proyti_cepochku(fl_ctx *ctx, fl_value shagi, fl_value hod, fl_value obstanovka, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Пройти цепочку", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_proyti_cepochku_body(ctx, shagi, hod, obstanovka, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

