/* Тело «Пройти посылки»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_proyti_posylki_body(fl_ctx *ctx, fl_value posylki, fl_value svod, fl_value obstanovka, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(posylki)) {
      *result = svod;
      return FL_OK;
    } else if (fl_chain_cons(posylki)) {
      const fl_value g = fl_chain_head(posylki); /* голова «г» */
      const fl_value h = fl_chain_tail(posylki); /* хвост «х» */
      fl_value fl_t26763 = fl_nothing();
      FL_TRY(kompilyator_flang_uchest_posylku(ctx, g, svod, obstanovka, &fl_t26763, error));
      const fl_value fl_t26764 = obstanovka;
      posylki = h;
      svod = fl_t26763;
      obstanovka = fl_t26764;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пройти посылки", error));
      continue;
    } else {
      return fl_match_fail(ctx, posylki, error);
    }
  }
}

/*
 * Функция flang «Пройти посылки».
 *
 * Обычная (не тотальная): завершение не доказано, зацикливание не ловится.
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param posylki — «посылки»: список: «Значение»
 * @param svod — «свод»: «Свод посылок»
 * @param obstanovka — «обстановка»: «Обстановка терма»
 * @return значение: «Свод посылок»
 */
fl_status kompilyator_flang_proyti_posylki(fl_ctx *ctx, fl_value posylki, fl_value svod, fl_value obstanovka, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Пройти посылки", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_proyti_posylki_body(ctx, posylki, svod, obstanovka, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

