/* Тело «Пройти обязательства»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_proyti_obyazatelstva_body(fl_ctx *ctx, fl_value obyazatelstva, fl_value svod, fl_value programma, fl_value progony, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(obyazatelstva)) {
      *result = svod;
      return FL_OK;
    } else if (fl_chain_cons(obyazatelstva)) {
      const fl_value g = fl_chain_head(obyazatelstva); /* голова «г» */
      const fl_value h = fl_chain_tail(obyazatelstva); /* хвост «х» */
      fl_value fl_t27225 = fl_nothing();
      FL_TRY(kompilyator_flang_proverit_obyazatelstvo(ctx, g, svod, programma, progony, &fl_t27225, error));
      const fl_value fl_t27226 = programma;
      const fl_value fl_t27227 = progony;
      obyazatelstva = h;
      svod = fl_t27225;
      programma = fl_t27226;
      progony = fl_t27227;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Пройти обязательства", error));
      continue;
    } else {
      return fl_match_fail(ctx, obyazatelstva, error);
    }
  }
}

/*
 * Функция flang «Пройти обязательства».
 *
 * Обычная (не тотальная): завершение не доказано, зацикливание не ловится.
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param obyazatelstva — «обязательства»: список: «Значение»
 * @param svod — «свод»: «Свод проверки»
 * @param programma — «программа»: «Значение»
 * @param progony — «прогоны»: список: «Значение»
 * @return значение: «Свод проверки»
 */
fl_status kompilyator_flang_proyti_obyazatelstva(fl_ctx *ctx, fl_value obyazatelstva, fl_value svod, fl_value programma, fl_value progony, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Пройти обязательства", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_proyti_obyazatelstva_body(ctx, obyazatelstva, svod, programma, progony, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

